class Solution {
public:
    int firstUniqueFreq(vector<int>& nums) {
        vector<int> freq(100001, 0);
        for (int x : nums) ++freq[x];
        vector<int> howMany(nums.size() + 1, 0);
        for (int x = 1; x <= 100000; ++x)
            if (freq[x]) ++howMany[freq[x]];
        for (int x : nums)
            if (howMany[freq[x]] == 1) return x;
        return -1;
    }
};
